  PrepareTaskDispatch = {
  "mode": "runOnceForAllItems",
  "language": "javaScript",
  "jsCode": "const invocation = $('Plan Transition').first().json.taskInvocation;\nconst bindings = $input.all().map(item => item.json).filter(row => row.task === invocation.task && row.machine === invocation.machine && row.machineVersion === invocation.machineVersion);\nconst available = bindings.length === 1 && typeof bindings[0].workflowId === 'string' && !!bindings[0].workflowId.trim();\nreturn [{ json: { ...invocation, bindingAvailable: available, workflowId: available ? bindings[0].workflowId : '',\n  dispatchReason: available ? '' : 'Task requires exactly one machine/version/task binding with a workflowId.' } }];"
};

